CREATE TABLE "livro" (
    "livr_cd_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "livr_tx_titulo" VARCHAR(255) NOT NULL,
    "livr_nr_ano" INTEGER NOT NULL,
    "livr_cd_romancista" BIGINT NOT NULL,
    CONSTRAINT "pk_livro" PRIMARY KEY ("livr_cd_id"),
    CONSTRAINT "uk_livro_titulo" UNIQUE ("livr_tx_titulo"),
    CONSTRAINT "fk_livro_romancista" FOREIGN KEY ("livr_cd_romancista")
    REFERENCES "romancista" ("roma_cd_id")
);
